Definition init_statics1 (M : word -> option byte) : Prop :=
     (forall a : word, 0xfc878 <= bv_unsigned a < 0xfcc28 -> M a = None)
  /\ (forall a : word, RVMLOCKC <= bv_unsigned a < RVMLOCKC + 4 -> M a = None)      (* [comment removed for export] *)
  /\ rw_cells rsegs M 0xfc703 [C1 (Z_to_bv 8 0)]
  /\ rw_cells rsegs M 0xfc730 [C8 (Z_to_bv 64 4096)]
  /\ rw_cells rsegs M 0xc96d0 [C8 (Z_to_bv 64 0xfc6e0)]
  /\ (exists canary : Z, 0 <= canary < 2 ^ 64 /\ rw_cells rsegs M 0xfc6e0 [C8 (Z_to_bv 64 canary)])
  /\ (exists (av : Z) (L : list (Z * Z)) (rnd secret : Z),
         rw_cells rsegs M 0xfc708 [C8 (Z_to_bv 64 av)]
      /\ bytes_at rsegs M av (u64s (map (Z_to_bv 64) (flat_pairs L ++ [0; 0])))
      /\ bytes_at rsegs M (rnd + 8) (le8 (Z_to_bv 64 secret))
      /\ (sptop <= av /\ av + 16 * (Z.of_nat (length L) + 1) <= 2 ^ 64 /\ sptop <= rnd + 8 /\ rnd + 16 <= 2 ^ 64
          /\ 0 <= rnd < 2 ^ 64 /\ 0 <= secret < 2 ^ 64)
      /\ Forall (fun p => fst p <> 0) L /\ last_assoc 25 L = Some rnd
      /\ Forall (fun p => fst p = 25 -> snd p = rnd) L
      /\ Forall (fun p => 0 <= fst p < 2 ^ 64 /\ 0 <= snd p < 2 ^ 64) L)
  /\ mem_inv rsegs M.

